import { useState, useEffect } from 'react';
import HeroSection from './HeroSection';
import ServicesSection from './ServicesSection';
import ContactSection from './ContactSection';
import ChatWidget from './ChatWidget';
import { chatService } from '../service/chatService';

function Home() {
  const [conversations, setConversations] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [isChatOpen, setIsChatOpen] = useState(false);

  useEffect(() => {
    loadUserConversations();
  }, []);

  const loadUserConversations = async () => {
    try {
      const token = localStorage.getItem('token');
      if (token) {
        const data = await chatService.getConversations(token);
        setConversations(data);
        if (data.length > 0) {
          setCurrentConversation(data[0]);
        }
      }
    } catch (error) {
      console.error('Erreur chargement conversations:', error);
    }
  };

  const handleNewConversation = async (title, message) => {
    try {
      const token = localStorage.getItem('token');
      const newConv = await chatService.createConversation(
        { title, message_text: message },
        token
      );

      setConversations(prev => [newConv, ...prev]);
      setCurrentConversation(newConv);
      setIsChatOpen(true);

      return newConv;
    } catch (error) {
      console.error('Erreur création conversation:', error);
      throw error;
    }
  };

  const handleSendMessage = async (messageText) => {
    if (!currentConversation) return;

    try {
      const token = localStorage.getItem('token');
      await chatService.sendMessage(
        currentConversation.id,
        { message_text: messageText, message_type: 'text' },
        token
      );

      await loadUserConversations();
    } catch (error) {
      console.error('Erreur envoi message:', error);
      throw error;
    }
  };

  return (
    <>
      <HeroSection onStartChat={() => setIsChatOpen(true)} />
      <ServicesSection />
      <ContactSection onStartChat={() => setIsChatOpen(true)} />

      <ChatWidget
        isOpen={isChatOpen}
        onClose={() => setIsChatOpen(false)}
        onOpen={() => setIsChatOpen(true)}
        conversations={conversations}
        currentConversation={currentConversation}
        onSelectConversation={setCurrentConversation}
        onNewConversation={handleNewConversation}
        onSendMessage={handleSendMessage}
        onLoadConversations={loadUserConversations}
      />
    </>
  );
}

export default Home;
